<script nonce="{{ $cspNonce }}">
(()=>{const body=document.body,openButton=document.querySelector('[data-sidebar-open]'),closeButtons=document.querySelectorAll('[data-sidebar-close]'),sidebar=document.getElementById('panel-navigation'),mobile=window.matchMedia('(max-width:820px)'),focusable='a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';const syncSidebar=()=>{const hidden=mobile.matches&&!body.classList.contains('sidebar-open');if(sidebar){sidebar.inert=hidden;sidebar.setAttribute('aria-hidden',String(hidden))}};const closeSidebar=(restore=true)=>{body.classList.remove('sidebar-open');openButton?.setAttribute('aria-expanded','false');syncSidebar();if(restore)openButton?.focus()};const openSidebar=()=>{body.classList.add('sidebar-open');openButton?.setAttribute('aria-expanded','true');syncSidebar();sidebar?.querySelector('[data-sidebar-close]')?.focus()};openButton?.addEventListener('click',openSidebar);closeButtons.forEach(button=>button.addEventListener('click',()=>closeSidebar()));document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(body.classList.contains('sidebar-open'))closeSidebar();document.querySelectorAll('.user-menu[open]').forEach(menu=>menu.removeAttribute('open'))}if(event.key==='Tab'&&mobile.matches&&body.classList.contains('sidebar-open')&&sidebar){const items=[...sidebar.querySelectorAll(focusable)].filter(item=>!item.inert&&item.offsetParent!==null);if(!items.length)return;const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});document.addEventListener('click',event=>{document.querySelectorAll('.user-menu[open]').forEach(menu=>{if(!menu.contains(event.target))menu.removeAttribute('open')})});mobile.addEventListener('change',()=>{if(!mobile.matches)closeSidebar(false);syncSidebar()});syncSidebar()})();
</script>
